import fs from 'node:fs';import{gzipSync}from'node:zlib';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&/^(sceneset|scenefire)_/.test(w))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}

function params(kind){return kind==='all'?{ref:'scene:scene-1',colorIndex:20,tempo:130.1,tempoEnabled:true,signatureNumerator:3,signatureDenominator:8,timeSignatureEnabled:true}:kind==='tempo'?{ref:'scene:scene-1',tempo:140}:kind==='signature'?{ref:'scene:scene-1',signatureNumerator:3,signatureDenominator:8}:kind==='switches'?{ref:'scene:scene-1',tempoEnabled:true,timeSignatureEnabled:true}:kind==='fire'?{ref:'scene:scene-1'}:{ref:'scene:scene-1',colorIndex:20};}
function alter(s,kind){const scene=s.scenes[0];if(kind==='tempo'||kind==='all')scene.tempo=180;else if(kind==='signature')scene.signatureNumerator=7;else if(kind==='switches')scene.tempoEnabled=false;else scene.colorIndex=22;}
const rows=[];
for(const family of ['scene','fire'])for(const action of ['preview','apply']){
 const valid=action==='preview'?params(family==='fire'?'fire':'all'):{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};
 const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];
 for(const key of Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,0.5,1,19.9,20,69,70,99,100,999,1000,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}
 for(const args of cases){const sim=new DeterministicLiveSimulator(),host=new McpHost(sim);const method=`liveScene${family==='fire'?'Fire':''}${action==='preview'?'Preview':'Apply'}Async`;rows.push({family,action,args,result:clean(await host[method](1,args))});}
}
const workflows=[];
for(const kind of ['color','tempo','signature','switches','all','fire'])for(const scenario of (kind==='fire'?['normal','expire','epoch','identity-edit','source-content','missing-identity','missing-scene','empty','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','fire-trigger','fire-transport','fire-target','fire-delayed','fire-never','fire-disappear']:['normal','expire','epoch','identity-edit','source-content','unrequested-content','null-prior','missing-prior','disabled-prior','bad-enabled-prior','high-prior','missing-identity','sibling-identity','missing-scene','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-clamped','apply-float32','apply-disappear','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-content','undo-unrequested-content','undo-epoch','undo-disappear'])){
 const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false,fireReads=0;
 const scene=sim.state.scenes[0];if(scenario==='missing-identity')delete scene.objectIdentity;if(scenario==='missing-scene')sim.state.scenes=[];if(scenario==='empty')scene.isEmpty=true;if(scenario==='sibling-identity')sim.state.scenes.push({...scene,ref:'scene:scene-2',objectIdentity:''});
 if(scenario==='null-prior')for(const f of ['colorIndex','tempo','tempoEnabled','signatureNumerator','signatureDenominator','timeSignatureEnabled'])scene[f]=null;
 if(scenario==='missing-prior')for(const f of ['colorIndex','tempo','tempoEnabled','signatureNumerator','signatureDenominator','timeSignatureEnabled'])delete scene[f];
 if(['disabled-prior','bad-enabled-prior','high-prior'].includes(scenario)){scene.tempo=scenario==='high-prior'?1000:-1;scene.signatureNumerator=scenario==='high-prior'?100:-1;scene.signatureDenominator=scenario==='high-prior'?100:-1;scene.tempoEnabled=scenario==='bad-enabled-prior';scene.timeSignatureEnabled=scenario==='bad-enabled-prior';}
 function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
 function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
 function mutateFire(){if(kind!=='fire'||!scenario.startsWith('fire-'))return;const scene=sim.state.scenes[0];if(scene)scene.isTriggered=false;sim.state.playback.transport.playing=false;sim.state.playback.firedTargets=[];sim.state.playback.playingTargets=[];if(scenario==='fire-trigger')scene.isTriggered=true;if(scenario==='fire-transport')sim.state.playback.transport.playing=true;if(scenario==='fire-target')sim.state.playback.playingTargets=[{sceneRef:'scene:scene-1',trackRef:'track:other',clipSlotRef:'clip-slot:other',sceneIndex:0,clipRef:null}];if(scenario==='fire-disappear'){sim.state.scenes=[];sim.state.playback.transport.playing=true;}}
 function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;mutateFire();if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&fault==='apply-clamped'){fired=true;alter(sim.state,kind);}if(!fired&&fault==='apply-float32'){fired=true;if(i.args.tempo!==undefined)sim.state.scenes[0].tempo=Math.fround(i.args.tempo);}if(!fired&&fault.endsWith('disappear')){fired=true;sim.state.scenes=[];}return result;}
 const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();if(afterInvoke&&scenario==='fire-delayed'&&++fireReads===3)sim.state.playback.transport.playing=true;return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
 const host=new McpHost(adapter),results=[],states=[];host.waitFor=async()=>{};const preview=await host[kind==='fire'?'liveSceneFirePreviewAsync':'liveScenePreviewAsync'](1,params(kind));results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text),txid=body.transactionId;
 if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host[kind==='fire'?'liveSceneFireApplyAsync':'liveSceneApplyAsync'](results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
 if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')scene.objectIdentity='other';if(scenario==='source-content'){if(kind==='fire')sim.state.playback.transport.playing=true;else alter(sim.state,kind);}if(scenario==='unrequested-content')scene.name='Manual';if(scenario.startsWith('apply-'))fault=scenario;
 for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
 if(kind!=='fire'){if(scenario==='undo-other-identity')scene.objectIdentity='other';if(scenario==='undo-other-content')alter(sim.state,kind);if(scenario==='undo-unrequested-content')scene.name='Manual';if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-unrequested-content','undo-epoch'].includes(scenario))fault=scenario;
 for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}}
 workflows.push({kind,scenario,results,states,calls,state:sim.state});
}
fs.writeFileSync(new URL('host-scene-oracle.json.gz',import.meta.url),gzipSync(JSON.stringify({rows,workflows}),{level:9}));console.log({rows:rows.length,workflows:workflows.length});
